#include "augmatch/filter.hpp"
#include <cuda_runtime.h>
#include <cstdio>
#include <vector>
int main(){int devices=0;if(cudaGetDeviceCount(&devices)!=cudaSuccess||devices==0)return 77;const int w=8,h=6,n=w*h;std::vector<unsigned char> host(n,90),result(n);std::vector<float> depth(n,.5f),ox(3,0),oy(3,0),rows(h,0);unsigned char *di=nullptr,*do_=nullptr;float *dd=nullptr,*dx=nullptr,*dy=nullptr;cudaMalloc(&di,n);cudaMalloc(&do_,n);cudaMalloc(&dd,n*sizeof(float));cudaMalloc(&dx,3*sizeof(float));cudaMalloc(&dy,3*sizeof(float));cudaMemcpy(di,host.data(),n,cudaMemcpyHostToDevice);cudaMemcpy(dd,depth.data(),n*sizeof(float),cudaMemcpyHostToDevice);cudaMemcpy(dx,ox.data(),3*sizeof(float),cudaMemcpyHostToDevice);cudaMemcpy(dy,oy.data(),3*sizeof(float),cudaMemcpyHostToDevice);augmatch::depth_dependent_defocus_u8(di,do_,{w,h,1,dd,.5f,5,4});cudaDeviceSynchronize();cudaMemcpy(result.data(),do_,n,cudaMemcpyDeviceToHost);if(result!=host)return 1;augmatch::camera_shake_blur_u8(di,do_,{w,h,1,3,dx,dy});cudaDeviceSynchronize();cudaMemcpy(result.data(),do_,n,cudaMemcpyDeviceToHost);if(result!=host)return 2;cudaFree(di);cudaFree(do_);cudaFree(dd);cudaFree(dx);cudaFree(dy);return 0;}
